-- Refund request and encrypted-destination control plane. Cash approval/attempt posting follows in a separate source kernel.
grant create on schema api,app_private,finance_private to git_tutor_commands;
create table finance_private.refunds(id uuid primary key default gen_random_uuid(),source_type text not null check(source_type in('charge','unapplied_credit')),source_id uuid not null,payer_binding_id uuid not null references finance_private.transfer_payer_bindings(id),payer_account_id uuid not null references app_private.accounts(id),requested_by uuid not null references app_private.accounts(id),learner_id uuid references app_private.learners(id),requested_minor bigint not null check(requested_minor between 1 and 9007199254740991),approved_minor bigint check(approved_minor between 1 and 9007199254740991),currency text not null check(currency='EGP'),reason text not null,requires_remedy boolean not null,remedy_id uuid,destination_version_id uuid,state text not null default 'requested' check(state in('requested','approved','pending','settled','partially_reversed','reversed','failed','unknown','cancelled')),approved_by uuid references app_private.accounts(id),approved_at timestamptz,version integer not null default 1,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table finance_private.refund_destinations(id uuid primary key,refund_id uuid not null references finance_private.refunds(id),payer_account_id uuid not null references app_private.accounts(id),channel text not null check(channel in('instapay','vodafone_cash')),identifier_version integer not null default 1 check(identifier_version=1),encrypted_identifier jsonb not null,masked_identifier text not null,identifier_fingerprint text not null check(identifier_fingerprint~'^[a-f0-9]{64}$'),payee_name text not null,source_evidence_file_id uuid not null references app_private.files(id),ciphertext_digest text not null check(ciphertext_digest~'^[a-f0-9]{64}$'),verification_status text not null default 'unverified' check(verification_status in('unverified','verified','rejected')),proposed_by uuid not null references app_private.accounts(id),propose_command_id uuid not null,propose_idempotency_key text not null,propose_request jsonb not null,version integer not null default 1,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(proposed_by,propose_idempotency_key));
create table finance_private.destination_validation_artifacts(id uuid primary key default gen_random_uuid(),actor_account_id uuid not null references app_private.accounts(id),auth_session_id uuid not null,destination_id uuid not null references finance_private.refund_destinations(id),destination_version integer not null,ciphertext_digest text not null,masked_identifier text not null,identifier_fingerprint text not null,purpose text not null check(purpose='verify_refund_destination'),approval_request jsonb not null,approval_request_hash text not null,expires_at timestamptz not null,consumed_at timestamptz,consumed_command_id uuid,created_at timestamptz not null default now());
create table finance_private.refund_destination_versions(id uuid primary key default gen_random_uuid(),destination_id uuid not null references finance_private.refund_destinations(id),version_number integer not null,payer_account_id uuid not null references app_private.accounts(id),channel text not null,encrypted_identifier jsonb not null,masked_identifier text not null,identifier_fingerprint text not null,ciphertext_digest text not null,ownership_evidence_file_id uuid not null references app_private.files(id),verified_by uuid not null references app_private.accounts(id),verified_at timestamptz not null default now(),validation_artifact_id uuid not null unique references finance_private.destination_validation_artifacts(id),unique(destination_id,version_number));
alter table finance_private.refunds add foreign key(destination_version_id) references finance_private.refund_destination_versions(id);
create table finance_private.refund_source_reservations(id uuid primary key default gen_random_uuid(),refund_id uuid not null references finance_private.refunds(id),credit_reservation_id uuid not null unique references finance_private.credit_reservations(id),transfer_id uuid not null references finance_private.incoming_transfers(id),credit_lot_id uuid not null references finance_private.customer_credit_lots(id),source_allocation_id uuid references finance_private.payment_allocations(id),remedy_reservation_id uuid references app_private.remedy_reservations(id),amount_minor bigint not null check(amount_minor between 1 and 9007199254740991),created_at timestamptz not null default now());
create table finance_private.refund_attempts(id uuid primary key default gen_random_uuid(),refund_id uuid not null references finance_private.refunds(id),previous_attempt_id uuid references finance_private.refund_attempts(id),destination_version_id uuid not null references finance_private.refund_destination_versions(id),external_reference text not null,state text not null default 'pending' check(state in('pending','settled','failed','unknown')),started_at timestamptz not null default now(),version integer not null default 1,command_id uuid not null,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(destination_version_id,external_reference));
create table finance_private.refund_outcomes(id uuid primary key default gen_random_uuid(),attempt_id uuid not null references finance_private.refund_attempts(id),outcome text not null check(outcome in('settled','failed','unknown','reversed')),evidence_file_id uuid not null references app_private.files(id),external_reference text not null,settled_at timestamptz,ledger_transaction_id uuid references finance_private.ledger_transactions(id),actor_account_id uuid not null references app_private.accounts(id),command_id uuid not null,recorded_at timestamptz not null default now());
create unique index refund_settlement_once on finance_private.refund_outcomes(attempt_id) where outcome='settled';
create table finance_private.refund_reversals(id uuid primary key default gen_random_uuid(),refund_id uuid not null references finance_private.refunds(id),attempt_id uuid not null references finance_private.refund_attempts(id),channel text not null,external_reversal_id text not null,amount_minor bigint not null check(amount_minor between 1 and 9007199254740991),evidence_file_id uuid not null references app_private.files(id),ledger_transaction_id uuid not null references finance_private.ledger_transactions(id),actor_account_id uuid not null references app_private.accounts(id),command_id uuid not null,source_line_key text not null,effective_at timestamptz not null,recorded_at timestamptz not null default now(),unique(channel,external_reversal_id),unique(command_id,source_line_key));
create table finance_private.refund_reversal_sources(id uuid primary key default gen_random_uuid(),refund_reversal_id uuid not null references finance_private.refund_reversals(id),refund_source_reservation_id uuid not null references finance_private.refund_source_reservations(id),transfer_id uuid not null references finance_private.incoming_transfers(id),payer_binding_id uuid not null references finance_private.transfer_payer_bindings(id),amount_minor bigint not null check(amount_minor>0),returned_credit_lot_id uuid not null references finance_private.customer_credit_lots(id) deferrable initially deferred,command_id uuid not null,created_at timestamptz not null default now(),unique(refund_reversal_id,refund_source_reservation_id));
alter table finance_private.customer_credit_lots add foreign key(source_refund_reversal_id) references finance_private.refund_reversals(id) deferrable initially deferred;
alter table finance_private.ledger_lines add foreign key(refund_id) references finance_private.refunds(id),add foreign key(attempt_id) references finance_private.refund_attempts(id) deferrable initially deferred;
create function app_private.refund_source_immutable() returns trigger language plpgsql set search_path='' as $$declare allowed text[];begin if tg_op='DELETE' then raise exception 'IMMUTABLE_VERSION';end if;allowed:=case tg_table_name when 'refunds' then array['approved_minor','remedy_id','destination_version_id','state','approved_by','approved_at','version','updated_at'] when 'refund_destinations' then array['verification_status','version','updated_at'] when 'destination_validation_artifacts' then array['consumed_at','consumed_command_id'] when 'refund_attempts' then array['state','version','updated_at'] else '{}'::text[] end;if(to_jsonb(old)-allowed) is distinct from(to_jsonb(new)-allowed) or(tg_table_name='destination_validation_artifacts' and to_jsonb(old)->>'consumed_at' is not null) then raise exception 'IMMUTABLE_VERSION';end if;return new;end $$;
create function app_private.refund_assert_scope(p_actor uuid,p_refund_id uuid,p_owner_only boolean default false) returns finance_private.refunds language plpgsql security definer set search_path='' as $$
declare r finance_private.refunds%rowtype;begin select * into r from finance_private.refunds where id=p_refund_id;if r.id is null then raise exception 'NOT_FOUND';end if;if app_private.has_role(p_actor,'admin') or r.payer_account_id=p_actor then return r;end if;if p_owner_only or r.learner_id is null then raise exception 'FORBIDDEN';end if;perform app_private.package_assert_scope(p_actor,r.learner_id,'payments');return r;end $$;
create function app_private.payment_server_actor(p_actor uuid,p_session uuid,p_admin boolean default false) returns void language plpgsql security definer set search_path='' as $$begin if not coalesce(app_private.auth_session_active(p_actor,p_session),false) then raise exception 'SESSION_REVOKED';end if;if not coalesce(app_private.payment_verified_account(p_actor),false) then raise exception 'VERIFIED_ACCOUNT_REQUIRED';end if;if p_admin then perform app_private.require_role(p_actor,'admin');end if;end $$;
create function api.request_refund(p_source_type text,p_source_id uuid,p_payer_account_id uuid,p_amount_minor bigint,p_reason text,p_idempotency_key text) returns jsonb language plpgsql security definer set search_path='' as $$
declare actor uuid:=app_private.require_actor();payer uuid;binding uuid;learner uuid;context jsonb;r finance_private.refunds%rowtype;amount numeric;needs_remedy boolean:=true;begin
 if p_source_type='unapplied_credit' then
  select b.payer_account_id,b.id into payer,binding from finance_private.incoming_transfers t join finance_private.transfer_payer_bindings b on b.id=t.current_payer_binding_id where t.id=p_source_id;
  if payer is null then raise exception 'NOT_FOUND';end if;if payer<>actor and not app_private.has_role(actor,'admin') then raise exception 'FORBIDDEN';end if;
  if p_payer_account_id is not null and p_payer_account_id<>payer then raise exception 'FORBIDDEN';end if;
 elsif p_source_type='charge' then
  select learner_id into learner from finance_private.charges where id=p_source_id;if learner is null then raise exception 'NOT_FOUND';end if;
  if not app_private.has_role(actor,'admin') and not exists(select 1 from finance_private.payment_allocations a join finance_private.transfer_payer_bindings b on b.id=a.payer_binding_id where a.charge_id=p_source_id and b.payer_account_id=actor) then perform app_private.package_assert_scope(actor,learner,'payments');end if;
  if p_payer_account_id is not null then payer:=p_payer_account_id;elsif exists(select 1 from finance_private.payment_allocations a join finance_private.transfer_payer_bindings b on b.id=a.payer_binding_id where a.charge_id=p_source_id and b.payer_account_id=actor) then payer:=actor;
  else select case when count(distinct b.payer_account_id)=1 then (array_agg(b.payer_account_id))[1] end into payer from finance_private.payment_allocations a join finance_private.transfer_payer_bindings b on b.id=a.payer_binding_id where a.charge_id=p_source_id;end if;
  if payer is null then raise exception 'CONSENT_REQUIRED';end if;
  if payer<>actor and not app_private.has_role(actor,'admin') and exists(select 1 from finance_private.payment_allocations a join finance_private.transfer_payer_bindings b on b.id=a.payer_binding_id where a.charge_id=p_source_id and b.payer_account_id<>payer) then raise exception 'FORBIDDEN';end if;
  select b.id into binding from finance_private.payment_allocations a join finance_private.transfer_payer_bindings b on b.id=a.payer_binding_id where a.charge_id=p_source_id and b.payer_account_id=payer order by a.recorded_at,a.id limit 1;if binding is null then raise exception 'NOT_FOUND';end if;
 else raise exception 'VALIDATION_ERROR';end if;
 context:=app_private.booking_begin(actor,'request_refund',jsonb_build_object('source_type',p_source_type,'source_id',p_source_id,'payer_account_id',p_payer_account_id,'amount_minor',p_amount_minor,'reason',p_reason),p_idempotency_key);if context->'replay_result'<>'null'::jsonb then return context->'replay_result';end if;
 if p_amount_minor is null or p_amount_minor not between 1 and 9007199254740991 or p_reason is null or length(btrim(p_reason)) not between 1 and 2000 then raise exception 'VALIDATION_ERROR';end if;
 if p_source_type='unapplied_credit' then amount:=(finance_private.finance_transfer_balance(p_source_id)->>'available_minor')::bigint;needs_remedy:=p_amount_minor>finance_private.finance_refundable_surplus(p_source_id);
 else select coalesce(sum(a.amount_minor),0) into amount from finance_private.payment_allocations a join finance_private.transfer_payer_bindings b on b.id=a.payer_binding_id where a.charge_id=p_source_id and b.payer_account_id=payer;end if;
 if p_amount_minor>amount then raise exception 'INSUFFICIENT_FUNDS';end if;
 insert into finance_private.refunds(source_type,source_id,payer_binding_id,payer_account_id,requested_by,learner_id,requested_minor,currency,reason,requires_remedy) values(p_source_type,p_source_id,binding,payer,actor,learner,p_amount_minor,'EGP',btrim(p_reason),needs_remedy) returning * into r;perform set_config('response.status','201',true);
 return app_private.booking_finish(context,r.id,r.version,jsonb_build_object('refund_id',r.id,'state','requested'),'refund_requested',jsonb_build_object('refund_id',r.id));
end $$;
create function app_private.prepare_refund_destination_context(p_actor_account_id uuid,p_auth_session_id uuid,p_refund_id uuid,p_idempotency_key text) returns jsonb language plpgsql security definer set search_path='' as $$
declare r finance_private.refunds%rowtype;prior jsonb;begin perform app_private.payment_server_actor(p_actor_account_id,p_auth_session_id);r:=app_private.refund_assert_scope(p_actor_account_id,p_refund_id,true);if p_idempotency_key is null or length(p_idempotency_key) not between 1 and 200 then raise exception 'VALIDATION_ERROR';end if;
 select d.propose_request into prior from finance_private.refund_destinations d join app_private.command_results c on c.id=d.propose_command_id and c.actor_account_id=d.proposed_by and c.command_name='propose_refund_destination' and c.idempotency_key=d.propose_idempotency_key where d.refund_id=r.id and d.proposed_by=p_actor_account_id and d.propose_idempotency_key=p_idempotency_key;
 return jsonb_build_object('payer_account_id',r.payer_account_id,'prior_request',prior);end $$;
create function api.propose_refund_destination(p_refund_id uuid,p_destination_id uuid,p_channel text,p_encrypted_identifier jsonb,p_masked_identifier text,p_identifier_fingerprint text,p_payee_name text,p_source_evidence_file_id uuid,p_expected_version integer,p_idempotency_key text) returns jsonb language plpgsql security definer set search_path='' as $$
declare actor uuid:=app_private.require_actor();r finance_private.refunds%rowtype;context jsonb;request jsonb;d finance_private.refund_destinations%rowtype;begin
 r:=app_private.refund_assert_scope(actor,p_refund_id,true);request:=jsonb_build_object('p_refund_id',p_refund_id,'p_destination_id',p_destination_id,'p_channel',p_channel,'p_encrypted_identifier',p_encrypted_identifier,'p_masked_identifier',p_masked_identifier,'p_identifier_fingerprint',p_identifier_fingerprint,'p_payee_name',p_payee_name,'p_source_evidence_file_id',p_source_evidence_file_id,'p_expected_version',p_expected_version,'p_idempotency_key',p_idempotency_key);
 context:=app_private.booking_begin(actor,'propose_refund_destination',request,p_idempotency_key);if context->'replay_result'<>'null'::jsonb then return context->'replay_result';end if;
 select * into r from finance_private.refunds where id=r.id for update;if r.version is distinct from p_expected_version then raise exception 'VERSION_CONFLICT';end if;if r.state not in('requested','failed') then raise exception 'STATE_CONFLICT';end if;
 if p_destination_id is null or p_channel is null or p_channel not in('instapay','vodafone_cash') or p_payee_name is null or length(btrim(p_payee_name)) not between 1 and 200 or p_masked_identifier is null or p_masked_identifier!~'^••••( [A-Za-z0-9]{4})?$' or p_identifier_fingerprint is null or p_identifier_fingerprint!~'^[a-f0-9]{64}$' then raise exception 'VALIDATION_ERROR';end if;
 if jsonb_typeof(p_encrypted_identifier) is distinct from 'object' or p_encrypted_identifier-array['v','alg','kid','nonce','ciphertext','tag']<>'{}'::jsonb or p_encrypted_identifier->'v' is distinct from '1'::jsonb or not(p_encrypted_identifier ?& array['v','alg','kid','nonce','ciphertext','tag']) or exists(select 1 from jsonb_each(p_encrypted_identifier) x where x.key<>'v' and jsonb_typeof(x.value)<>'string') or p_encrypted_identifier->>'alg' is distinct from 'A256GCM' or coalesce(p_encrypted_identifier->>'kid','')!~'^[A-Za-z0-9_-]{1,40}$' or coalesce(p_encrypted_identifier->>'nonce','')!~'^[A-Za-z0-9_-]{16}$' or coalesce(p_encrypted_identifier->>'tag','')!~'^[A-Za-z0-9_-]{22}$' or coalesce(p_encrypted_identifier->>'ciphertext','')!~'^[A-Za-z0-9_-]{1,1024}$' then raise exception 'VALIDATION_ERROR';end if;
 perform app_private.payment_assert_file(p_source_evidence_file_id,'refund_destination','refund',r.id,actor);
 insert into finance_private.refund_destinations(id,refund_id,payer_account_id,channel,encrypted_identifier,masked_identifier,identifier_fingerprint,payee_name,source_evidence_file_id,ciphertext_digest,proposed_by,propose_command_id,propose_idempotency_key,propose_request) values(p_destination_id,r.id,r.payer_account_id,p_channel,p_encrypted_identifier,p_masked_identifier,p_identifier_fingerprint,btrim(p_payee_name),p_source_evidence_file_id,app_private.catalog_hash(p_encrypted_identifier),actor,(context->>'command_id')::uuid,p_idempotency_key,request) returning * into d;
 update finance_private.refunds set version=version+1,updated_at=now() where id=r.id;perform set_config('response.status','201',true);
 return app_private.booking_finish(context,d.id,d.version,jsonb_build_object('destination_id',d.id,'masked_identifier',d.masked_identifier,'verification_status','unverified'),'refund_destination_proposed',jsonb_build_object('refund_id',r.id,'destination_id',d.id));
end $$;
create function app_private.read_refund_destination_for_server(p_actor_account_id uuid,p_auth_session_id uuid,p_destination_id uuid,p_purpose text,p_refund_attempt_id uuid default null,p_reason text default null) returns jsonb language plpgsql security definer set search_path='' as $$
declare d finance_private.refund_destinations%rowtype;verified uuid;begin perform app_private.payment_server_actor(p_actor_account_id,p_auth_session_id,true);select * into d from finance_private.refund_destinations where id=p_destination_id;if d.id is null then raise exception 'NOT_FOUND';end if;perform app_private.refund_assert_scope(p_actor_account_id,d.refund_id,true);
 select id into verified from finance_private.refund_destination_versions where destination_id=d.id order by version_number desc limit 1;
 if p_purpose='verify_candidate' then if p_refund_attempt_id is not null then raise exception 'VALIDATION_ERROR';end if;
 elsif p_purpose='reveal_for_attempt' then if p_reason is null or length(btrim(p_reason)) not between 1 and 2000 or not exists(select 1 from finance_private.refund_attempts a join finance_private.refund_destination_versions v on v.id=a.destination_version_id where a.id=p_refund_attempt_id and a.refund_id=d.refund_id and v.destination_id=d.id and a.state in('pending','unknown')) then raise exception 'FORBIDDEN';end if;
 else raise exception 'VALIDATION_ERROR';end if;
 insert into app_private.audit_events(actor_account_id,command_id,action,aggregate_id,details) values(p_actor_account_id,gen_random_uuid(),'refund_identifier_accessed',d.id,jsonb_build_object('purpose',p_purpose,'attempt_id',p_refund_attempt_id,'reason',p_reason));
 return jsonb_build_object('destination_id',d.id,'refund_id',d.refund_id,'payer_account_id',d.payer_account_id,'channel',d.channel,'identifier_version',1,'version',d.version,'encrypted_identifier',d.encrypted_identifier,'ciphertext_digest',d.ciphertext_digest,'masked_identifier',d.masked_identifier,'identifier_fingerprint',d.identifier_fingerprint,'verification_status',d.verification_status,'destination_version_id',verified);
end $$;
create function app_private.issue_destination_validation_artifact(p_actor_account_id uuid,p_auth_session_id uuid,p_destination_id uuid,p_destination_version integer,p_ciphertext_digest text,p_masked_identifier text,p_identifier_fingerprint text,p_purpose text,p_approval_request jsonb) returns jsonb language plpgsql security definer set search_path='' as $$
declare d finance_private.refund_destinations%rowtype;a finance_private.destination_validation_artifacts%rowtype;prior app_private.command_results%rowtype;hash text;begin
 perform app_private.payment_server_actor(p_actor_account_id,p_auth_session_id,true);select * into d from finance_private.refund_destinations where id=p_destination_id;if d.id is null then raise exception 'NOT_FOUND';end if;perform app_private.refund_assert_scope(p_actor_account_id,d.refund_id,true);
 if p_purpose is distinct from 'verify_refund_destination' or jsonb_typeof(p_approval_request) is distinct from 'object' or p_approval_request-array['destination_id','expected_version','evidence_file_id','decision','reason','idempotency_key']<>'{}'::jsonb or not(p_approval_request ?& array['destination_id','expected_version','evidence_file_id','decision','reason','idempotency_key']) or jsonb_typeof(p_approval_request->'expected_version') is distinct from 'number' or exists(select 1 from jsonb_each(p_approval_request) x where x.key<>'expected_version' and jsonb_typeof(x.value)<>'string') or p_approval_request->>'destination_id' is distinct from d.id::text or p_approval_request->>'decision' not in('verified','rejected') or length(btrim(coalesce(p_approval_request->>'reason',''))) not between 1 and 2000 or length(coalesce(p_approval_request->>'idempotency_key','')) not between 1 and 200 then raise exception 'VALIDATION_ERROR';end if;
 hash:=app_private.catalog_hash(p_approval_request);
 select * into prior from app_private.command_results where actor_account_id=p_actor_account_id and command_name='verify_refund_destination' and idempotency_key=p_approval_request->>'idempotency_key';
 if prior.id is not null then select * into a from finance_private.destination_validation_artifacts where consumed_command_id=prior.id and actor_account_id=p_actor_account_id and destination_id=d.id and approval_request_hash=hash;if a.id is null then raise exception 'IDEMPOTENCY_CONFLICT';end if;return jsonb_build_object('validation_artifact_id',a.id,'approval_request_hash',a.approval_request_hash,'expires_at',a.expires_at);end if;
 if d.version is distinct from p_destination_version or(p_approval_request->>'expected_version')::int is distinct from d.version then raise exception 'VERSION_CONFLICT';end if;
 if d.ciphertext_digest is distinct from p_ciphertext_digest or d.masked_identifier is distinct from p_masked_identifier or d.identifier_fingerprint is distinct from p_identifier_fingerprint or d.verification_status<>'unverified' then raise exception 'VALIDATION_ERROR';end if;
 insert into finance_private.destination_validation_artifacts(actor_account_id,auth_session_id,destination_id,destination_version,ciphertext_digest,masked_identifier,identifier_fingerprint,purpose,approval_request,approval_request_hash,expires_at) values(p_actor_account_id,p_auth_session_id,d.id,d.version,d.ciphertext_digest,d.masked_identifier,d.identifier_fingerprint,p_purpose,p_approval_request,hash,now()+interval '5 minutes') returning * into a;
 return jsonb_build_object('validation_artifact_id',a.id,'approval_request_hash',a.approval_request_hash,'expires_at',a.expires_at);
end $$;
create function api.verify_refund_destination(p_destination_id uuid,p_evidence_file_id uuid,p_decision text,p_reason text,p_validation_artifact_id uuid,p_expected_version integer,p_idempotency_key text) returns jsonb language plpgsql security definer set search_path='' as $$
declare actor uuid:=app_private.require_actor();session uuid:=(current_setting('request.jwt.claims',true)::jsonb->>'session_id')::uuid;d finance_private.refund_destinations%rowtype;a finance_private.destination_validation_artifacts%rowtype;context jsonb;approval jsonb;version_id uuid;version integer;begin
 perform app_private.require_role(actor,'admin');select * into d from finance_private.refund_destinations where id=p_destination_id;if d.id is null then raise exception 'NOT_FOUND';end if;
 approval:=jsonb_build_object('destination_id',p_destination_id,'expected_version',p_expected_version,'evidence_file_id',p_evidence_file_id,'decision',p_decision,'reason',p_reason,'idempotency_key',p_idempotency_key);
 context:=app_private.booking_begin(actor,'verify_refund_destination',approval||jsonb_build_object('validation_artifact_id',p_validation_artifact_id),p_idempotency_key);if context->'replay_result'<>'null'::jsonb then return context->'replay_result';end if;
 perform 1 from finance_private.refunds where id=d.refund_id for update;select * into d from finance_private.refund_destinations where id=d.id for update;select * into a from finance_private.destination_validation_artifacts where id=p_validation_artifact_id for update;
 if d.version is distinct from p_expected_version then raise exception 'VERSION_CONFLICT';end if;
 if a.id is null or a.actor_account_id<>actor or a.auth_session_id<>session or a.destination_id<>d.id or a.destination_version<>d.version or a.expires_at<=now() or a.consumed_at is not null or a.ciphertext_digest<>d.ciphertext_digest or a.approval_request_hash<>app_private.catalog_hash(approval) then raise exception 'FORBIDDEN';end if;
 if p_decision is null or p_decision not in('verified','rejected') or p_reason is null or length(btrim(p_reason)) not between 1 and 2000 or d.verification_status<>'unverified' then raise exception 'VALIDATION_ERROR';end if;
 perform app_private.payment_assert_file(p_evidence_file_id,'refund_destination_verification','refund_destination',d.id);
 if p_decision='verified' then insert into finance_private.refund_destination_versions(destination_id,version_number,payer_account_id,channel,encrypted_identifier,masked_identifier,identifier_fingerprint,ciphertext_digest,ownership_evidence_file_id,verified_by,validation_artifact_id) values(d.id,1,d.payer_account_id,d.channel,d.encrypted_identifier,d.masked_identifier,d.identifier_fingerprint,d.ciphertext_digest,p_evidence_file_id,actor,a.id) returning id into version_id;end if;
 update finance_private.destination_validation_artifacts set consumed_at=now(),consumed_command_id=(context->>'command_id')::uuid where id=a.id;
 update finance_private.refund_destinations set verification_status=p_decision,version=refund_destinations.version+1,updated_at=now() where id=d.id returning refund_destinations.version into version;
 return app_private.booking_finish(context,d.id,version,jsonb_build_object('destination_version_id',version_id,'verification_status',p_decision),'refund_destination_verified',jsonb_build_object('destination_id',d.id,'decision',p_decision));
end $$;
create function app_private.payment_refund_dto(p_refund_id uuid,p_actor uuid) returns jsonb language plpgsql stable security definer set search_path='' as $$
declare r finance_private.refunds%rowtype;destination jsonb;reserved numeric;settled numeric;returned numeric;begin select * into r from finance_private.refunds where id=p_refund_id;if r.id is null then raise exception 'NOT_FOUND';end if;
 select jsonb_build_object('destination_version_id',v.id,'channel',v.channel,'masked_identifier',v.masked_identifier,'verification_status','verified') into destination from finance_private.refund_destination_versions v where v.id=r.destination_version_id;
 select coalesce(sum(s.amount_minor),0) into reserved from finance_private.refund_source_reservations s join finance_private.credit_reservations c on c.id=s.credit_reservation_id where s.refund_id=r.id and c.state='reserved';
 select coalesce(sum(r.approved_minor),0) into settled from finance_private.refund_attempts a join finance_private.refund_outcomes o on o.attempt_id=a.id and o.outcome='settled' where a.refund_id=r.id;
 select coalesce(sum(amount_minor),0) into returned from finance_private.refund_reversals where refund_id=r.id;
 return jsonb_build_object('refund_id',r.id,'version',r.version,'source_type',r.source_type,'source_id',r.source_id,'amount_minor',coalesce(r.approved_minor,r.requested_minor),'currency',r.currency,'state',r.state,'requested_at',r.created_at,'approved_at',r.approved_at,'reserved_minor',reserved,'settled_minor',settled,'returned_minor',returned,'can_propose_destination',(r.payer_account_id=p_actor or app_private.has_role(p_actor,'admin')) and r.state in('requested','failed'),'requires_remedy',r.requires_remedy,'destination',destination,'next_action',case r.state when 'requested' then 'Provide a verified destination and await review' when 'approved' then 'Await the recorded outgoing attempt' when 'pending' then 'Await independent outcome evidence' when 'unknown' then 'Reconcile the existing attempt before any retry' when 'failed' then 'Review failure evidence before retry' when 'settled' then 'Refund settled' else 'Review the recorded refund state' end);
end $$;
create or replace function app_private.payment_source_refunds_page(p_actor uuid,p_source_type text,p_source_id uuid,p_cursor text,p_limit integer) returns jsonb language plpgsql stable security definer set search_path='' as $$
declare after_at timestamptz;after_id uuid;rows jsonb;begin
 if p_source_type='charge' then perform app_private.package_assert_scope(p_actor,(select learner_id from finance_private.charges where id=p_source_id),'payments',true);
 elsif p_source_type='unapplied_credit' then if not app_private.has_role(p_actor,'admin') and not exists(select 1 from finance_private.incoming_transfers t join finance_private.transfer_payer_bindings b on b.id=t.current_payer_binding_id where t.id=p_source_id and b.payer_account_id=p_actor) then raise exception 'FORBIDDEN';end if;
 else raise exception 'VALIDATION_ERROR';end if;
 if p_limit is null or p_limit not between 1 and 100 then raise exception 'VALIDATION_ERROR';end if;if p_cursor is not null then if length(p_cursor)>200 or array_length(string_to_array(p_cursor,'|'),1)<>2 then raise exception 'VALIDATION_ERROR';end if;after_at:=split_part(p_cursor,'|',1)::timestamptz;after_id:=split_part(p_cursor,'|',2)::uuid;end if;
 select coalesce(jsonb_agg(jsonb_build_object('id',x.id,'at',x.created_at,'data',app_private.payment_refund_dto(x.id,p_actor)) order by x.created_at desc,x.id desc),'[]') into rows from(select r.* from finance_private.refunds r where r.source_type=p_source_type and r.source_id=p_source_id and(p_cursor is null or(r.created_at,r.id)<(after_at,after_id)) order by r.created_at desc,r.id desc limit p_limit+1)x;return app_private.package_page(rows,p_limit);
end $$;
create function api.get_refund(p_refund_id uuid) returns jsonb language plpgsql security definer set search_path='' as $$declare actor uuid:=app_private.require_actor();begin perform app_private.refund_assert_scope(actor,p_refund_id);return app_private.payment_refund_dto(p_refund_id,actor);end $$;
create function app_private.payment_refunds_page(p_actor uuid,p_admin boolean,p_state text,p_cursor text,p_limit integer) returns jsonb language plpgsql stable security definer set search_path='' as $$
declare after_at timestamptz;after_id uuid;rows jsonb;begin if p_admin then perform app_private.require_role(p_actor,'admin');end if;if p_limit is null or p_limit not between 1 and 100 or(p_state is not null and p_state not in('requested','approved','pending','settled','partially_reversed','reversed','failed','unknown','cancelled')) then raise exception 'VALIDATION_ERROR';end if;if p_cursor is not null then if length(p_cursor)>200 or array_length(string_to_array(p_cursor,'|'),1)<>2 then raise exception 'VALIDATION_ERROR';end if;after_at:=split_part(p_cursor,'|',1)::timestamptz;after_id:=split_part(p_cursor,'|',2)::uuid;end if;
 select coalesce(jsonb_agg(jsonb_build_object('id',x.id,'at',x.created_at,'data',app_private.payment_refund_dto(x.id,p_actor)) order by x.created_at desc,x.id desc),'[]') into rows from(select r.* from finance_private.refunds r where(p_admin or r.payer_account_id=p_actor or app_private.package_can_access(p_actor,r.learner_id)) and(p_state is null or r.state=p_state) and(p_cursor is null or(r.created_at,r.id)<(after_at,after_id)) order by r.created_at desc,r.id desc limit p_limit+1)x;return app_private.package_page(rows,p_limit);end $$;
create function api.list_my_refunds(p_cursor text default null,p_limit integer default 25) returns jsonb language sql security definer set search_path='' as $$select app_private.payment_refunds_page(app_private.require_actor(),false,null,p_cursor,p_limit)$$;
create function api.list_admin_refunds(p_state text default null,p_cursor text default null,p_limit integer default 25) returns jsonb language sql security definer set search_path='' as $$select app_private.payment_refunds_page(app_private.require_actor(),true,p_state,p_cursor,p_limit)$$;
create function api.list_refund_destinations(p_refund_id uuid,p_cursor text default null,p_limit integer default 25) returns jsonb language plpgsql security definer set search_path='' as $$
declare actor uuid:=app_private.require_actor();after_at timestamptz;after_id uuid;rows jsonb;begin perform app_private.refund_assert_scope(actor,p_refund_id);if p_limit is null or p_limit not between 1 and 100 then raise exception 'VALIDATION_ERROR';end if;if p_cursor is not null then if length(p_cursor)>200 or array_length(string_to_array(p_cursor,'|'),1)<>2 then raise exception 'VALIDATION_ERROR';end if;after_at:=split_part(p_cursor,'|',1)::timestamptz;after_id:=split_part(p_cursor,'|',2)::uuid;end if;
 select coalesce(jsonb_agg(jsonb_build_object('id',x.id,'at',x.created_at,'data',jsonb_build_object('destination_id',x.id,'version',x.version,'identifier_version',1,'destination_version_id',(select id from finance_private.refund_destination_versions where destination_id=x.id order by version_number desc limit 1),'channel',x.channel,'masked_identifier',x.masked_identifier,'payee_name',x.payee_name,'verification_status',x.verification_status,'created_at',x.created_at)) order by x.created_at desc,x.id desc),'[]') into rows from(select d.* from finance_private.refund_destinations d where d.refund_id=p_refund_id and(p_cursor is null or(d.created_at,d.id)<(after_at,after_id)) order by d.created_at desc,d.id desc limit p_limit+1)x;return app_private.package_page(rows,p_limit);end $$;
do $$declare name text;f record;begin foreach name in array array['refunds','refund_destinations','destination_validation_artifacts','refund_destination_versions','refund_source_reservations','refund_attempts','refund_outcomes','refund_reversals','refund_reversal_sources'] loop execute format('alter table finance_private.%I enable row level security',name);execute format('create policy commands_access on finance_private.%I to git_tutor_commands using(true) with check(true)',name);execute format('grant select,insert on finance_private.%I to git_tutor_commands',name);execute format('revoke all on finance_private.%I from public,anon,authenticated,service_role,git_tutor_worker',name);execute format('create trigger immutable_refund_source before update or delete on finance_private.%I for each row execute function app_private.refund_source_immutable()',name);end loop;
 grant update on finance_private.refunds,finance_private.refund_destinations,finance_private.destination_validation_artifacts,finance_private.refund_attempts to git_tutor_commands;
 for f in select p.oid::regprocedure::text signature,n.nspname,p.proname from pg_proc p join pg_namespace n on n.oid=p.pronamespace where(n.nspname='app_private' and p.proname in('refund_source_immutable','refund_assert_scope','payment_server_actor','prepare_refund_destination_context','read_refund_destination_for_server','issue_destination_validation_artifact','payment_refund_dto','payment_source_refunds_page','payment_refunds_page')) or(n.nspname='api' and p.proname in('request_refund','propose_refund_destination','verify_refund_destination','get_refund','list_my_refunds','list_admin_refunds','list_refund_destinations')) loop execute format('alter function %s owner to git_tutor_commands',f.signature);execute format('revoke all on function %s from public,anon,authenticated,service_role,git_tutor_worker',f.signature);if f.nspname='api' then execute format('grant execute on function %s to authenticated',f.signature);elsif f.proname in('prepare_refund_destination_context','read_refund_destination_for_server','issue_destination_validation_artifact') then execute format('grant execute on function %s to git_tutor_worker',f.signature);end if;end loop;
end $$;
revoke create on schema api,app_private,finance_private from git_tutor_commands;
notify pgrst,'reload schema';

